// Ruqyah content generated by scripts/convert-ruqyah.mjs.
import fs from "node:fs/promises";
import path from "node:path";
import { cache } from "react";
import type { QuranVerse } from "./night-prayer";

export type RuqyahTopic = "all" | "protection" | "eye" | "magic" | "healing";

export type RuqyahItem = {
  title: string;
  benefit: string;
  topics: Exclude<RuqyahTopic, "all">[];
  repeat?: number;
  verses?: QuranVerse[];
  refAr?: string;
  refEn?: string;
  text?: string;
  source?: string;
};

export type RuqyahContent = { guide: string[]; quran: RuqyahItem[]; duas: RuqyahItem[] };

export const getRuqyahContent = cache(
  async (): Promise<RuqyahContent> =>
    JSON.parse(await fs.readFile(path.join(process.cwd(), "data/ruqyah/content.json"), "utf8")),
);
